import{z as B,x as l,o as r,c as d,q as t,j as i,D as e,d as n,s as A,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"叙事与高频识别","description":"","frontmatter":{"title":"叙事与高频识别","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/narrative-hf-identification.md","filePath":"econ/narrative-hf-identification.md","lastUpdated":1791413859000}'),m={name:"econ/narrative-hf-identification.md"};function p(c,a,F,f,D,R){const o=l("Mermaid");return r(),d("div",null,[a[2]||(a[2]=t('<h1 id="叙事与高频识别" tabindex="-1">叙事与高频识别 <a class="header-anchor" href="#叙事与高频识别" aria-label="Permalink to &quot;叙事与高频识别&quot;">​</a></h1><div class="epigraph"><p>冲击的标签若不能从同期零限制放心得到，就从历史记录或政策公告窗里的价格跳变去借。</p><footer>—— Romer and Romer, A New Measure of Monetary Shocks: Derivation and Implications, AER 2004；Gertler and Karadi, Monetary Policy Surprises, Credit Costs, and Economic Activity, AEJ:Macro 2015；Ramey 财政叙事</footer></div><p><a href="/econ/local-projections">上一课</a>把 IRF 估计从 VAR 套牢里拆出，并声明冲击仍须外来。本课缺口是<strong>冲击从哪来</strong>：叙事（读档案、读绿皮书）与高频（公告窗内期货跳变）。本单元在此收束识别；下一单元进入异质性。不重写 LP 公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Cholesky 对货币、财政都脆。Romer–Romer：用绿皮书预测把「对经济状况的内生反应」从意向利率里减掉，残差当叙事货币冲击。Ramey：军费新闻日期。Mertens–Ravn：叙事减税。Gertler–Karadi、Gürkaynak–Sack–Swanson：FOMC 公告窗内联邦基金或欧洲美元期货的跳变，当意外。缺口是给 SVAR/LP 一条外部 \\(\\varepsilon\\) 或工具，而不是再排一次变量顺序。</p><p><span class="marginnote">术语翻译：「内生反应」就是央行的条件反射——经济一软它就降息。直接拿利率变动当「货币政策冲击」，等于把果当成因；Romer–Romer 的做法是先用央行自己的预测把这一层反射减掉，剩下的才算意外。</span></p><p><span class="marginnote">Romer and Romer, <em>AER</em> 94(4), 2004。Gertler and Karadi, <em>AEJ:Macro</em> 7(1), 2015。Nakamura and Steinsson, <em>QJE</em> 2018 用高频看信息效应。Kuttner 的联邦基金期货是前身。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>叙事：编码规则必须事前，防止用 IRF 形状反过来挑日期。把叙事序列当冲击直接 LP，或当代理进 SVAR（Mertens–Ravn）。高频：窗要短到宏观数据进不来、长到价格能反应；多目标（路径、前瞻指引）用若干期货期限抽因子。信息效应：若公告同时揭示央行的经济判断，利率升可能伴随股票升，工具就不是纯政策供给——要显式建模或选正交化。</p><p><span class="marginnote">数字实例：FOMC 声明下午 2 点发布，取 2:00 到 2:30 的联邦基金期货跳变当意外——窗再宽，之后的宏观数据与解读新闻就会掺进来；窄于几分钟，价格可能还没反应完。窗宽是拿「干净」换「听得见」。</span></p>',10)),(r(),i(s,null,{default:e(()=>[A(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAR%5B%22%E5%8F%99%E4%BA%8B%E6%AE%8B%E5%B7%AE%22%5D%20--%3E%20IV%5B%22%E5%BD%93%20%CE%B5%20%E6%88%96%E5%B7%A5%E5%85%B7%22%5D%0A%20%20HF%5B%22%E5%85%AC%E5%91%8A%E7%AA%97%E6%9C%9F%E8%B4%A7%E8%B7%B3%22%5D%20--%3E%20IV%0A%20%20IV%20--%3E%20LP%5B%22LP%20%2F%20%E4%BB%A3%E7%90%86%20SVAR%22%5D%0A%20%20INFO%5B%22%E4%BF%A1%E6%81%AF%E6%95%88%E5%BA%94%22%5D%20--%3E%20BIAS%5B%22%E6%B1%A1%E6%9F%93%E6%A0%87%E7%AD%BE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"财政与货币共用这一逻辑，冲击账户不同。本课不把区域乘数的 Bartik 写进来，以免换数据维度。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是用制度时间线或市场时钟制造外生变异。叙事靠人读条件信息；高频靠市场比宏观更早把意外资本化。两者都可能弱（工具与真 \\(\\varepsilon\\) 相关低）或污染（混进新闻）。弱工具使 LP-IV 的远地平线不可信。DSGE 估计可以把这些序列当额外观测，把结构冲击与代理对齐——回到贝叶斯课的接口，不重估 SW。",-1)),(r(),i(s,null,{default:e(()=>[A(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAR%5B%22%E5%8F%99%E4%BA%8B%E8%AF%86%E5%88%AB%3A%20%E9%9D%A0%E5%88%B6%E5%BA%A6%E6%97%B6%E9%97%B4%E7%BA%BF%22%5D%20--%3E%20N1%5B%22%E8%AF%BB%E7%BB%BF%E7%9A%AE%E4%B9%A6%E6%88%96%E5%86%9B%E8%B4%B9%E6%96%B0%E9%97%BB%22%5D%0A%20%20N1%20--%3E%20N2%5B%22%E5%87%8F%E6%8E%89%E5%AF%B9%E7%BB%8F%E6%B5%8E%E7%9A%84%E5%86%85%E7%94%9F%E5%8F%8D%E5%BA%94%22%5D%0A%20%20N2%20--%3E%20N3%5B%22%E6%80%95%3A%20%E4%BA%8B%E5%90%8E%E6%8C%91%E6%97%A5%E6%9C%9F%2C%20%E7%BC%96%E7%A0%81%E4%B8%8D%E5%B9%B2%E5%87%80%22%5D%0A%20%20HF%5B%22%E9%AB%98%E9%A2%91%E8%AF%86%E5%88%AB%3A%20%E9%9D%A0%E5%B8%82%E5%9C%BA%E6%97%B6%E9%92%9F%22%5D%20--%3E%20H1%5B%22%E5%85%AC%E5%91%8A%E7%AA%97%E5%86%85%E6%9C%9F%E8%B4%A7%E8%B7%B3%E5%8F%98%22%5D%0A%20%20H1%20--%3E%20H2%5B%22%E7%AA%97%E7%9F%AD%E5%88%B0%E5%AE%8F%E8%A7%82%E6%95%B0%E6%8D%AE%E8%BF%9B%E4%B8%8D%E6%9D%A5%22%5D%0A%20%20H2%20--%3E%20H3%5B%22%E6%80%95%3A%20%E4%BF%A1%E6%81%AF%E6%95%88%E5%BA%94%E6%B7%B7%E8%BF%9B%E6%94%BF%E7%AD%96%E6%84%8F%E5%A4%96%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">常见误区：以为「拿到外部冲击序列」就万事大吉。若它与真冲击相关很弱，LP-IV 的远处脉冲会爆炸性地不可信——估计像被放大镜拉长，标准误却装作不知道。弱工具要报第一阶段强度，不是只画 IRF。</span></p><p>本课程动态方法单元在此停：能解、能估、能识别加总脉冲。加总脉冲对「谁的 MPC」沉默——下一单元从代表性个体走开。</p><p><span class="marginnote">Ramey, <em>Handbook of Macroeconomics</em> 第 2 卷，财政与货币识别综述。Jarociński and Karadi 把信息效应与纯政策在符号上拆开。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重建绿皮书数据库，不交易期货。不把高频识别写成微观结构（不是 Kyle）。量化宽松的期限溢价通道可点名，不把整本央行资产负债表提前写完（金融摩擦单元后部）。太阳黑子与新闻冲击（Beaudry–Portier）是预期单元的题目。</p><p>后课默认：外部冲击序列来自叙事或高频（或两者作代理）；LP/SVAR 只是第二步。下一课：加总欧拉背后，不完全市场的资产分布。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>叙事从档案构造条件残差；高频从公告窗价格跳变借意外。</li><li>可当冲击或 IV；信息效应会污染标签。</li><li>识别单元结束；加总 IRF 不回答异质 MPC。</li><li>出处：Romer and Romer, <em>AER</em> 2004；Gertler and Karadi, <em>AEJ:Macro</em> 2015；Ramey 手册。</li></ul>',8))])}const P=B(m,[["render",p]]);export{u as __pageData,P as default};
